/// <summary>
/// Sales order invoice posted business event.
/// </summary>
[BusinessEvents(classStr(METSalesInvoicePostedBusinessEventContract), '@MET:SOInvoiceBusinessEvent', '@MET:SOInvoiceBusinessEventDesc', ModuleAxapta::SalesOrder)]
public final class METSalesInvoicePostedBusinessEvent extends BusinessEventsBase
{
    private CustInvoiceJour custInvoiceJour; 

}

Method.Source:
    /// <summary>
    /// gets/sets the custInvoiceJour buffer
    /// </summary>
    /// <param name = "_custInvoiceJour">custInvoiceJour buffer</param>
    /// <returns>custInvoiceJour buffer</returns>
    private CustInvoiceJour parmCustInvoiceJour(CustInvoiceJour _custInvoiceJour = custInvoiceJour)
    {
        custInvoiceJour = _custInvoiceJour;

        return custInvoiceJour;
    }

    /// <summary>
    /// Creates a <c>METSalesInvoicePostedBusinessEvent</c> from a <c>CustInvoiceJour</c> record.
    /// </summary>
    /// <param name = "_custInvoiceJour"> A <c>CustInvoiceJour</c> record.</param>
    /// <returns>A <c>SalesInvoicePostedBusinessEvent</c>.</returns>
    public static METSalesInvoicePostedBusinessEvent newFromCustInvoiceJour(CustInvoiceJour _custInvoiceJour)
    {
        METSalesInvoicePostedBusinessEvent businessEvent = new METSalesInvoicePostedBusinessEvent();
        businessEvent.parmCustInvoiceJour(_custInvoiceJour);

        return businessEvent;
    }

/// <summary>
/// Constructs a new METSalesInvoicePostedBusinessEventContract business event data contract.
/// </summary>
/// <returns>
/// A new <c>METSalesInvoicePostedBusinessEventContract</c> business event data contract.
/// </returns>
[Wrappable(true), Replaceable(true)]
public BusinessEventsContract buildContract()
{
    return METSalesInvoicePostedBusinessEventContract::newFromCustInvoiceJour(custInvoiceJour);
}
